import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{o as a,c as o,a as r}from"./chunks/runtime-core.esm-bundler.zrDZb-cq.js";const d=JSON.parse('{"title":"polymuse — композитор на нескольких агентах","description":"Бриф на YAML превращается в партитуру, её проверяет критик, потом рендер в MIDI и WAV. Неровные метры, несколько циклов, живые партии.","frontmatter":{"site":"creative","title":"polymuse — композитор на нескольких агентах","description":"Бриф на YAML превращается в партитуру, её проверяет критик, потом рендер в MIDI и WAV. Неровные метры, несколько циклов, живые партии.","head":[["link",{"rel":"canonical","href":"https://alterfo.ru/projects/polymuse"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"polymuse — композитор на нескольких агентах"}],["meta",{"property":"og:description","content":"Бриф на YAML превращается в партитуру, её проверяет критик, потом рендер в MIDI и WAV. Неровные метры, несколько циклов, живые партии."}],["meta",{"property":"og:url","content":"https://alterfo.ru/projects/polymuse"}],["meta",{"property":"og:image","content":"https://alterfo.ru/og.png"}],["meta",{"property":"og:site_name","content":"Alterfo"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"polymuse — композитор на нескольких агентах"}],["meta",{"name":"twitter:description","content":"Бриф на YAML превращается в партитуру, её проверяет критик, потом рендер в MIDI и WAV. Неровные метры, несколько циклов, живые партии."}],["meta",{"name":"twitter:image","content":"https://alterfo.ru/og.png"}]]},"headers":[],"relativePath":"projects/polymuse.md","filePath":"projects/polymuse.md"}'),l={name:"projects/polymuse.md"};function i(n,e,s,p,c,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="polymuse" tabindex="-1">polymuse <a class="header-anchor" href="#polymuse" aria-label="Permalink to &quot;polymuse&quot;">​</a></h1><p>Бриф на YAML — режим, темп, циклы, секции, настроение, целевая громкость — превращается в партитуру. Дальше её читает агент-критик, потом человек. Только после этого — рендер в MIDI и WAV.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brief.yaml → Score → critic → (human) → MIDI + WAV</span></span></code></pre></div><h2 id="зачем" tabindex="-1">Зачем <a class="header-anchor" href="#зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><p>Полиметрия руками пишется медленно: пока сведёшь три цикла в один такт, потеряешь идею. Мне хотелось задавать намерение словами и получать материал, который можно править, а не готовый трек «как у всех».</p><p>Критик нужен, чтобы не тащить в рендер явную ерунду. Он разбирает партитуру по тем же правилам, что и я: где голоса сталкиваются, где пропадает дыхание, где секция не работает.</p><h2 id="как-устроено" tabindex="-1">Как устроено <a class="header-anchor" href="#как-устроено" aria-label="Permalink to &quot;Как устроено&quot;">​</a></h2><ul><li>Партитура — данные, а не аудио. Её можно показать, сравнить, отредактировать.</li><li>Рендер идёт через инструмент Lumen: <code>lumen-kit --score</code> собирает звук из той же партитуры.</li><li>Оркестрация — несколько агентов с разными ролями: композитор, критик, аранжировщик.</li></ul><h2 id="состояние" tabindex="-1">Состояние <a class="header-anchor" href="#состояние" aria-label="Permalink to &quot;Состояние&quot;">​</a></h2><p>Работает, репозиторий закрытый. Слушать результат — в разделе <a href="/music.html">музыки</a>.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Больше форм: не только циклы, но и свободные разделы.</li><li>Сохранение правок человека обратно в бриф, чтобы следующая версия учитывала их.</li></ul>',12)])])}const y=t(l,[["render",i]]);export{d as __pageData,y as default};
